content.text:
{
  "name": "Linkam SDK封装组件",
  "name_en": "Linkam SDK Wrapper",
  "manufacturer": "Linkam",
  "description": "一个非实体的软件组件，用于初始化和管理 Linkam SDK，配置日志，并通过 USB 或 RS-232 与 Linkam 仪器建立连接。它还提供底层消息处理接口，便于实验控制软件调用厂商 SDK 与设备通信。",
  "description_en": "A non-physical software component that initializes and manages the Linkam SDK, configures logging, and establishes USB or RS-232 connections to Linkam instruments. It also provides low-level message-processing interfaces so laboratory control software can communicate with devices through the vendor SDK.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "初始化并打开 Linkam SDK 以供使用。",
      "description_en": "Initialize and open the Linkam SDK for use."
    },
    {
      "action_name": "auto-close",
      "description": "关闭并释放 Linkam SDK 相关资源。",
      "description_en": "Close the Linkam SDK and release related resources."
    },
    {
      "action_name": "auto-process_message",
      "description": "向 Linkam SDK 发送底层消息并处理返回结果。",
      "description_en": "Send a low-level message to the Linkam SDK and process the returned result."
    },
    {
      "action_name": "auto-process_message_str",
      "description": "向 Linkam SDK 发送消息并将字符串响应解码返回。",
      "description_en": "Send a message to the Linkam SDK and decode the returned string response."
    },
    {
      "action_name": "auto-set_logging_level",
      "description": "设置 Linkam SDK 的日志级别。",
      "description_en": "Set the logging level of the Linkam SDK."
    },
    {
      "action_name": "auto-connect_serial",
      "description": "通过 RS-232 串口连接到 Linkam 仪器。",
      "description_en": "Connect to a Linkam instrument over an RS-232 serial port."
    },
    {
      "action_name": "auto-connect_usb",
      "description": "通过 USB 连接到 Linkam 仪器。",
      "description_en": "Connect to a Linkam instrument over USB."
    },
    {
      "action_name": "auto-connect",
      "description": "按配置选择串口或 USB 方式连接 Linkam 仪器。",
      "description_en": "Connect to a Linkam instrument using either serial or USB according to configuration."
    }
  ],
  "tag_hints": [
    "Linkam SDK",
    "non-physical software component",
    "instrument connectivity",
    "USB instrument connection",
    "RS-232 instrument connection",
    "SDK message processing",
    "logging control"
  ]
}

